@ITreeBridge.from_itree
     : forall (E MN : Type -> Type) (A : Type),
       ITreeDefinition.itree E A -> PTreeDefinition.ptree E MN A

@ITreeBridge.interp_itree
     : forall (E F MN : Type -> Type) (A : Type),
       Core.Handler.Handler MN E F -> ITreeDefinition.itree E A -> PTreeDefinition.ptree F MN A

@ITreeBridge.elaborate
     : forall (MN E : Type -> Type) (A : Type),
       ITreeDefinition.itree (Sum.sum1 (ITreeBridge.probE MN) E) A -> PTreeDefinition.ptree E MN A

@ITreeBridge.elaborate_closed
     : forall (MN : Type -> Type) (A : Type),
       ITreeDefinition.itree (ITreeBridge.probE MN) A -> PTreeDefinition.ptree Sum.void1 MN A

@ITreeBridge.observe_from_itree
     : forall (E MN : Type -> Type) (A : Type) (t : ITreeDefinition.itree E A),
       @PTreeDefinition.observe E MN A (@ITreeBridge.from_itree E MN A t) =
       match @ITreeDefinition.observe E A t with
       | @ITreeDefinition.RetF _ _ _ a =>
           @PTreeDefinition.RetF E MN A (PTreeDefinition.ptree E MN A) a
       | @ITreeDefinition.TauF _ _ _ u =>
           @PTreeDefinition.TauF E MN A (PTreeDefinition.ptree E MN A)
             (@ITreeBridge.from_itree E MN A u)
       | @ITreeDefinition.VisF _ _ _ X e k =>
           @PTreeDefinition.VisF E MN A (PTreeDefinition.ptree E MN A) X e
             (fun x : X => @ITreeBridge.from_itree E MN A (k x))
       end

@ITreeStructural.from_itree_ret
     : forall (E MN : Type -> Type) (A : Type) (a : A),
       @PStruct.pstruct E MN A A (@eq A)
         (@ITreeBridge.from_itree E MN A
            {|
              ITreeDefinition._observe := @ITreeDefinition.RetF E A (ITreeDefinition.itree E A) a
            |})
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.RetF E MN A (PTreeDefinition.ptree E MN A) a
         |}

@ITreeStructural.from_itree_tau
     : forall (E MN : Type -> Type) (A : Type) (t : ITreeDefinition.itree E A),
       @PStruct.pstruct E MN A A (@eq A)
         (@ITreeBridge.from_itree E MN A
            {|
              ITreeDefinition._observe := @ITreeDefinition.TauF E A (ITreeDefinition.itree E A) t
            |})
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.TauF E MN A (PTreeDefinition.ptree E MN A)
               (@ITreeBridge.from_itree E MN A t)
         |}

@ITreeStructural.from_itree_vis
     : forall (E MN : Type -> Type) (A X : Type) (e : E X) (k : X -> ITreeDefinition.itree E A),
       @PStruct.pstruct E MN A A (@eq A)
         (@ITreeBridge.from_itree E MN A
            {|
              ITreeDefinition._observe :=
                @ITreeDefinition.VisF E A (ITreeDefinition.itree E A) X e k
            |})
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.VisF E MN A (PTreeDefinition.ptree E MN A) X e
               (fun x : X => @ITreeBridge.from_itree E MN A (k x))
         |}

@ITreeStructural.interp_itree_ret
     : forall (E F MN : Type -> Type) (h : Core.Handler.Handler MN E F) (A : Type) (a : A),
       @PStruct.pstruct F MN A A (@eq A)
         (@ITreeBridge.interp_itree E F MN A h
            {|
