            |})
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.RetF F MN A (PTreeDefinition.ptree F MN A) a
         |}

@ITreeStructural.interp_itree_tau
     : forall (E F MN : Type -> Type) (h : Core.Handler.Handler MN E F)
         (A : Type) (t : ITreeDefinition.itree E A),
       @PStruct.pstruct F MN A A (@eq A)
         (@ITreeBridge.interp_itree E F MN A h
            {|
              ITreeDefinition._observe := @ITreeDefinition.TauF E A (ITreeDefinition.itree E A) t
            |})
