@ITreeStructural.interp_itree_vis
     : forall (E F MN : Type -> Type) (h : Core.Handler.Handler MN E F)
         (A X : Type) (e : E X) (k : X -> ITreeDefinition.itree E A),
       @PStruct.pstruct F MN A A (@eq A)
         (@ITreeBridge.interp_itree E F MN A h
            {|
              ITreeDefinition._observe :=
                @ITreeDefinition.VisF E A (ITreeDefinition.itree E A) X e k
            |})
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.TauF F MN A (PTreeDefinition.ptree F MN A)
               (@PTreeDefinition.PTree.bind F MN X A (h X e)
                  (fun x : X => @ITreeBridge.interp_itree E F MN A h (k x)))
         |}

@ITreeStructural.interp_itree_postcompose
     : forall (E F G MN : Type -> Type) (A : Type) (h : Core.Handler.Handler MN E F)
         (g : Core.Handler.Handler MN F G) (t : ITreeDefinition.itree E A),
       @PStruct.pstruct G MN A A (@eq A)
         (@PTreeDefinition.PTree.interp F G MN g A (@ITreeBridge.interp_itree E F MN A h t))
         (@ITreeBridge.interp_itree E G MN A (@Handler.cat MN E F G h g) t)

@ITreeStructural.elaborate_sample_structural
     : forall (MN E : Type -> Type) (A X : Type) (mu : MN X)
         (k : X -> ITreeDefinition.itree (Sum.sum1 (ITreeBridge.probE MN) E) A),
       @PStruct.pstruct E MN A A (@eq A)
         (@ITreeBridge.elaborate MN E A
            {|
              ITreeDefinition._observe :=
                @ITreeDefinition.VisF (Sum.sum1 (ITreeBridge.probE MN) E) A
                  (ITreeDefinition.itree (Sum.sum1 (ITreeBridge.probE MN) E) A) X
                  (@Sum.inl1 (ITreeBridge.probE MN) E X (@ITreeBridge.Sample MN X mu)) k
            |})
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.TauF E MN A (PTreeDefinition.ptree E MN A)
               {|
                 PTreeDefinition._observe :=
                   @PTreeDefinition.ProbF E MN A (PTreeDefinition.ptree E MN A) X mu
                     (fun x : X => @ITreeBridge.elaborate MN E A (k x))
               |}
         |}

