                @ITreeDefinition.VisF (Sum.sum1 (ITreeBridge.probE MN) E) A
                  (ITreeDefinition.itree (Sum.sum1 (ITreeBridge.probE MN) E) A) X
                  (@Sum.inr1 (ITreeBridge.probE MN) E X e) k
            |})
         {|
