       @RelationalClosure.relational_mixed_bind MN MF NI FI MX ->
       @RelationalClosure.relational_zero MF FI FO ->
       @RelationalClosure.relational_lub MF FI FO ->
       forall (E F : Type -> Type) (I A : Type) (h : Core.Handler.Handler MN E F)
         (step : I -> ITreeDefinition.itree E (I + A)) (i : I),
       @PEutt.peutt F MN MF FI FC MX FO A A (@eq A)
         (@ITreeBridge.interp_itree E F MN A h (@ITreeDefinition.ITree.iter E A I step i))
         (@PTreeDefinition.PTree.iter F MN A I
            (fun j : I => @ITreeBridge.interp_itree E F MN (I + A) h (step j)) i)

@ITreeFacts.elab_sample_trigger
     : forall (MN MF : Type -> Type) (NI : Measure.SemanticMeasure MN),
       @Measure.SemanticMeasureCoreLaws MN NI ->
       forall (FI : Measure.SemanticMeasure MF) (FC : @Measure.SemanticMeasureCoreLaws MF FI),
       @Measure.SemanticMeasureBindLaws MF FI ->
       forall (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @RelationalClosure.relational_mixed_bind MN MF NI FI MX ->
       @RelationalClosure.relational_zero MF FI FO ->
       @RelationalClosure.relational_lub MF FI FO ->
       forall (X : Type) (mu : MN X),
       @PEutt.peutt Sum.void1 MN MF FI FC MX FO X X (@eq X)
         (@ITreeBridge.elaborate_closed MN X
            (@ITreeDefinition.ITree.trigger (ITreeBridge.probE MN) X (@ITreeBridge.Sample MN X mu)))
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.ProbF Sum.void1 MN X (PTreeDefinition.ptree Sum.void1 MN X) X mu
               (fun x : X =>
                {|
                  PTreeDefinition._observe :=
                    @PTreeDefinition.RetF Sum.void1 MN X (PTreeDefinition.ptree Sum.void1 MN X) x
                |})
         |}

@ITreeFacts.elab_postcompose
     : forall (MN MF : Type -> Type) (NI : Measure.SemanticMeasure MN),
       @Measure.SemanticMeasureCoreLaws MN NI ->
       forall (FI : Measure.SemanticMeasure MF) (FC : @Measure.SemanticMeasureCoreLaws MF FI),
       @Measure.SemanticMeasureBindLaws MF FI ->
       forall (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @RelationalClosure.relational_mixed_bind MN MF NI FI MX ->
       @RelationalClosure.relational_zero MF FI FO ->
       @RelationalClosure.relational_lub MF FI FO ->
       forall (E F G : Type -> Type) (A : Type) (h : Core.Handler.Handler MN E F)
         (g : Core.Handler.Handler MN F G) (t : ITreeDefinition.itree E A),
       @PEutt.peutt G MN MF FI FC MX FO A A (@eq A)
         (@PTreeDefinition.PTree.interp F G MN g A (@ITreeBridge.interp_itree E F MN A h t))
         (@ITreeBridge.interp_itree E G MN A (@Handler.cat MN E F G h g) t)

@ITreeBridge.native_observation
     : forall (MN : Type -> Type) (X : Type) (mu : MN X),
       @PTreeDefinition.observe Sum.void1 MN X
         (@ITreeBridge.elaborate_closed MN X
            (@ITreeDefinition.ITree.trigger (ITreeBridge.probE MN) X (@ITreeBridge.Sample MN X mu))) =
       @PTreeDefinition.TauF Sum.void1 MN X (PTreeDefinition.ptree Sum.void1 MN X)
         (@PTreeDefinition.PTree.bind Sum.void1 MN X X
            {|
              PTreeDefinition._observe :=
                @PTreeDefinition.ProbF Sum.void1 MN X (PTreeDefinition.ptree Sum.void1 MN X) X mu
                  (fun x : X =>
                   {|
                     PTreeDefinition._observe :=
                       @PTreeDefinition.RetF Sum.void1 MN X (PTreeDefinition.ptree Sum.void1 MN X)
                         x
                   |})
            |}
            (fun x : X =>
             @ITreeBridge.interp_itree (ITreeBridge.probE MN) Sum.void1 MN X
               (@ITreeBridge.sample_handler MN Sum.void1)
               {|
                 ITreeDefinition._observe :=
                   @ITreeDefinition.RetF (ITreeBridge.probE MN) X
                     (ITreeDefinition.itree (ITreeBridge.probE MN) X) x
               |}))

@ITreeBridge.target_handler_postcomposition
     : forall (E F G MN : Type -> Type) (A : Type) (h : Core.Handler.Handler MN E F)
         (g : Core.Handler.Handler MN F G) (t : ITreeDefinition.itree E A),
       @PStruct.pstruct G MN A A (@eq A)
         (@PTreeDefinition.PTree.interp F G MN g A (@ITreeBridge.interp_itree E F MN A h t))
         (@ITreeBridge.interp_itree E G MN A (@Handler.cat MN E F G h g) t)

